using System.Reflection;
using System.Text;
using System.Text.Json;
using System.Xml;
using BinaryAssetBuilder.Core;
using BinaryAssetBuilder.Core.SageXml;

namespace BinaryAssetBuilder.ManifestInspector;

// Reborn: test usage semantics on private metadata fixtures and real EP1 schema types without compiling or publishing a user's mod.
internal static class SdkUnusedAssetAuditSmokeTest
{
    //-------------------------------------------------------------------------------------------------
    /** Reborn: every supported family is checked; stock/mod strong edges, weak aliases, overrides and cross-stream consumers prevent false unused reports. */
    //-------------------------------------------------------------------------------------------------
    internal static void Run(string output,string sdk)
    {
        if(Directory.Exists(output))throw new InvalidDataException("Fresh unused-audit evidence directory required.");Directory.CreateDirectory(output);
        string[] names={"GameObject","ArmorTemplate","WeaponTemplate","LogicCommand","LogicCommandSet","UpgradeTemplate","ObjectCreationList","AudioEvent","Texture","PackedTextureImage","W3DContainer","W3DHierarchy","W3DMesh","W3DCollisionBox","UnitAbilityButtonTemplate","JoypadCommandBarButtonTemplate","ExperienceLevelTemplate"};var candidates=names.Select(n=>Asset(n,"Unused"+n)).ToArray();Require(SdkUnusedAssetAudit.FindUnused(candidates,Array.Empty<ManifestAsset>(),Array.Empty<SdkUnusedAssetAudit.WeakUse>()).Length==names.Length-2,"Some asset types escaped unused detection.");
        var stockOwner=Asset("GameObject","StockOwner",WorldBuilderAssetResolver.Id(candidates[8]));var modOwner=Asset("GameObject","ModOwner",WorldBuilderAssetResolver.Id(candidates[1]));var weak=new SdkUnusedAssetAudit.WeakUse(WorldBuilderAssetResolver.Id(modOwner),new[]{WorldBuilderAssetResolver.Id(candidates[0]),WorldBuilderAssetResolver.Id(candidates[4]),WorldBuilderAssetResolver.Id(candidates[9])});var used=SdkUnusedAssetAudit.FindUnused(candidates.Append(modOwner),new[]{stockOwner},new[]{weak});foreach(int index in new[]{0,1,4,8,9})Require(!used.Any(a=>a.Name==candidates[index].Name),"Stock/mod strong or weak use was ignored: "+candidates[index].Name);
        var replaced=stockOwner with{References=Array.Empty<AssetId>(),AssetReferenceCount=0};Require(SdkUnusedAssetAudit.FindUnused(candidates.Append(replaced),new[]{stockOwner},Array.Empty<SdkUnusedAssetAudit.WeakUse>()).Any(a=>a.Name==candidates[8].Name),"Replaced stock owner kept an obsolete reference alive.");Require(!SdkUnusedAssetAudit.FindUnused(new[]{replaced},new[]{stockOwner},Array.Empty<SdkUnusedAssetAudit.WeakUse>()).Any(),"Retail override was mistaken for an unused runtime entry.");
        // Reborn: use actual local/typed and instance-chain merges, then round-trip their consumed inheritance through the preparation receipt.
        string inheritanceRoot=Path.Combine(output,"inheritance");Directory.CreateDirectory(inheritanceRoot);string inheritanceEntry=Path.Combine(inheritanceRoot,"entry.xml");
        File.WriteAllText(Path.Combine(inheritanceRoot,"library.xml"),"<!-- Reborn: only the selected instance chain is usage, not dormant library siblings. --><AssetDeclaration xmlns='uri:ea.com:eala:asset'><AudioEvent id='SourceAudioRoot'/><AudioEvent id='Intermediate' inheritFrom='AudioEvent:SourceAudioRoot'/><AudioEvent id='NeverUsed'/><AudioEvent id='DormantSourceOnly' inheritFrom='NeverUsed'/></AssetDeclaration>");
        File.WriteAllText(inheritanceEntry,"<!-- Reborn: literal and typed inheritance are consumed by real source preparation. --><AssetDeclaration xmlns='uri:ea.com:eala:asset'><Includes><Include type='instance' source='library.xml'/></Includes><AudioEvent id='UnusedAudioEvent'/><AudioEvent id='InheritedAudio' inheritFrom='AudioEvent:UnusedAudioEvent'/><AudioEvent id='ViaInstance' inheritFrom='Intermediate'/></AssetDeclaration>");
        string prepared=Path.Combine(inheritanceRoot,"prepared");ConscriptSourceInput.Prepare(inheritanceEntry,prepared);SdkSelfAttributeInheritance.Overlay[] inheritance;
        using(var receipt=JsonDocument.Parse(File.ReadAllBytes(Path.Combine(prepared,"source-input.json"))))inheritance=receipt.RootElement.GetProperty("InheritanceUses").Deserialize<SdkSelfAttributeInheritance.Overlay[]>()!;
        Require(inheritance.Any(e=>e.Type=="AudioEvent"&&e.DerivedId=="InheritedAudio"&&e.BaseId=="UnusedAudioEvent")&&inheritance.Any(e=>e.DerivedId=="Intermediate"&&e.BaseId=="SourceAudioRoot"),"Consumed local or source-only inheritance was lost from the receipt.");
        var inheritedAudio=Asset("AudioEvent","InheritedAudio");var viaInstance=Asset("AudioEvent","ViaInstance");var sourceAudioRoot=Asset("AudioEvent","SourceAudioRoot");var neverUsed=Asset("AudioEvent","NeverUsed");
        var inheritedFindings=SdkUnusedAssetAudit.FindUnused(new[]{candidates[7],inheritedAudio,viaInstance,sourceAudioRoot,neverUsed},Array.Empty<ManifestAsset>(),Array.Empty<SdkUnusedAssetAudit.WeakUse>(),inheritance);
        Require(!inheritedFindings.Any(a=>a.Name==candidates[7].Name||a.Name==sourceAudioRoot.Name)&&inheritedFindings.Any(a=>a.Name==neverUsed.Name),"Inheritance either lost a selected base chain or treated a dormant instance owner as emitted usage.");
        var upgradeChild=Asset("UpgradeTemplate","UpgradeChild");Require(!SdkUnusedAssetAudit.FindUnused(new[]{candidates[5],upgradeChild},Array.Empty<ManifestAsset>(),Array.Empty<SdkUnusedAssetAudit.WeakUse>(),new[]{new SdkSelfAttributeInheritance.Overlay("UpgradeTemplate","UpgradeChild","UnusedUpgradeTemplate")}).Any(a=>a.Name==candidates[5].Name),"Inheritance usage was incorrectly limited to audio.");
        Require(SdkUnusedAssetAudit.FindUnused(new[]{candidates[7]},Array.Empty<ManifestAsset>(),Array.Empty<SdkUnusedAssetAudit.WeakUse>(),inheritance).Any(),"An absent derived owner suppressed a truly unused audio base.");
        // Reborn: UI runtime selection is not an incoming manifest reference; unused ordinary assets must still warn next to those two families.
        var uiOnly=candidates.Where(a=>a.TypeName is "UnitAbilityButtonTemplate" or "JoypadCommandBarButtonTemplate").ToArray();Require(uiOnly.Length==2&&!SdkUnusedAssetAudit.FindUnused(uiOnly,Array.Empty<ManifestAsset>(),Array.Empty<SdkUnusedAssetAudit.WeakUse>()).Any(),"Runtime-selected UI templates were falsely classified as unused.");
        // Reborn: targeted experience levels are runtime roots, including a terminal rank with no incoming prerequisite edge.
        var level=candidates[^1];var target=WorldBuilderAssetResolver.Id(candidates[0]);var targeted=new SdkUnusedAssetAudit.WeakUse(WorldBuilderAssetResolver.Id(level),new[]{target});
        Require(!SdkUnusedAssetAudit.FindUnused(new[]{level,candidates[0]},Array.Empty<ManifestAsset>(),new[]{targeted}).Any(a=>a.TypeName=="ExperienceLevelTemplate"),"Targeted terminal experience level warned as unused.");
        Require(!SdkUnusedAssetAudit.FindUnused(new[]{level},new[]{candidates[0]},new[]{targeted}).Any(),"Retail GameObject target did not register an experience level.");
        var missing=new SdkUnusedAssetAudit.WeakUse(WorldBuilderAssetResolver.Id(level),new[]{WorldBuilderAssetResolver.Id(Asset("GameObject","MissingTarget"))});
        Require(SdkUnusedAssetAudit.FindUnused(new[]{level},Array.Empty<ManifestAsset>(),new[]{missing}).Any(),"Unknown experience target incorrectly suppressed unused detection.");
        var wrong=new SdkUnusedAssetAudit.WeakUse(WorldBuilderAssetResolver.Id(level),new[]{WorldBuilderAssetResolver.Id(candidates[5])});
        Require(SdkUnusedAssetAudit.FindUnused(new[]{level,candidates[5]},Array.Empty<ManifestAsset>(),new[]{wrong}).Any(a=>a.TypeName=="ExperienceLevelTemplate"),"A weak upgrade use was mistaken for a GameObject selector.");
        var levels=new List<ManifestAsset>();for(int rank=1;rank<=4;rank++)levels.Add(rank==1?Asset("ExperienceLevelTemplate","RebornRank1"):Asset("ExperienceLevelTemplate","RebornRank"+rank,WorldBuilderAssetResolver.Id(levels[^1])));
        Require(!SdkUnusedAssetAudit.FindUnused(levels.Append(candidates[0]),Array.Empty<ManifestAsset>(),levels.Select(a=>new SdkUnusedAssetAudit.WeakUse(WorldBuilderAssetResolver.Id(a),new[]{target}))).Any(),"A four-rank target-selected chain retained a false terminal-level warning.");
        var saved=Settings.Current;SdkUnusedAssetAudit.WeakUse[] schemaUses;
        try{
            Settings.Current=new Settings{SchemaPath=Path.Combine(Path.GetDirectoryName(ReferencePipelineSmokeTest.FindFixture())!,"TracerDrawPipeline.xsd"),BuildCache=false,StringHashBinDescriptors=Array.Empty<StringHashBinDescriptor>()};var schemas=new SchemaSet(false);foreach(var seed in schemas.Schemas.Schemas().Cast<System.Xml.Schema.XmlSchema>().ToArray())schemas.Schemas.Remove(seed);schemas.Schemas.Add(ConscriptSourceInput.Schemas());schemas.Schemas.Compile();typeof(SchemaSet).GetMethod("SetupHelperSchemaTypes",BindingFlags.Instance|BindingFlags.NonPublic)!.Invoke(schemas,null);
            var source=new XmlDocument{XmlResolver=null};source.Load(Path.Combine(Path.GetDirectoryName(ReferencePipelineSmokeTest.FindFixture())!,"live-alpha/ConscriptBuildTime1/data/mod.xml"));source.DocumentElement!.SetAttribute("id","ModOwner");source.DocumentElement.SetAttribute("CommandSet","UnusedLogicCommandSet");source.DocumentElement.SetAttribute("SelectPortrait","UnusedPackedTextureImage");source.DocumentElement.SetAttribute("ButtonImage","UnusedPackedTextureImage");var refs=SdkUnusedAssetAudit.WeakReferences(source.DocumentElement,source,schemas,candidates.Append(modOwner).ToArray());Require(refs.Contains(WorldBuilderAssetResolver.Id(candidates[4]))&&refs.Contains(WorldBuilderAssetResolver.Id(candidates[9])),"GameObject weak CommandSet/portrait references were lost.");
            var ocl=new XmlDocument{XmlResolver=null};ocl.LoadXml("<ObjectCreationList xmlns='uri:ea.com:eala:asset' id='Spawner'><CreateObject><CreateObject>UnusedGameObject</CreateObject></CreateObject></ObjectCreationList>");var spawns=SdkUnusedAssetAudit.WeakReferences(ocl.DocumentElement!,ocl,schemas,candidates);Require(spawns.Contains(WorldBuilderAssetResolver.Id(candidates[0])),"OCL weak spawn was lost.");// Reborn: use the real XSD Target field to produce the final-package receipt, rather than a synthetic incoming edge.
            var experience=new XmlDocument{XmlResolver=null};experience.LoadXml("<ExperienceLevelTemplate xmlns='uri:ea.com:eala:asset' id='UnusedExperienceLevelTemplate' Rank='3'><LevelUpTintColor r='1' g='1' b='1' a='1'/><Target>UnusedGameObject</Target></ExperienceLevelTemplate>");var selectors=SdkUnusedAssetAudit.WeakReferences(experience.DocumentElement!,experience,schemas,candidates);Require(selectors.Contains(target),"Experience Target weak selector was not captured from the official schema.");
            schemaUses=new[]{new SdkUnusedAssetAudit.WeakUse(WorldBuilderAssetResolver.Id(modOwner),refs.Concat(spawns).Distinct().ToArray()),new SdkUnusedAssetAudit.WeakUse(WorldBuilderAssetResolver.Id(level),selectors)};
        }finally{Settings.Current=saved;}
        // Reborn: a completed package containing separate static/global manifests is audited as one graph, never as isolated compiler invocations.
        byte[] templateBytes=File.ReadAllBytes(Path.Combine(sdk,"catalogs/ra3ep1/static.manifest"));var template=ManifestReader.Read(templateBytes);string fakeSdk=Path.Combine(output,"sdk"),catalogs=Path.Combine(fakeSdk,"catalogs/ra3ep1");Directory.CreateDirectory(catalogs);foreach(string file in new[]{"static.manifest","global.manifest","worldbuilder.manifest"})File.WriteAllBytes(Path.Combine(catalogs,file),Serialize(new[]{stockOwner})["diagnostic.manifest"]);
        var globals=new[]{candidates[1]};var staticAssets=candidates.Where(a=>a.Name!=candidates[1].Name).Concat(new[]{modOwner,inheritedAudio,viaInstance,sourceAudioRoot,neverUsed}).ToArray();var entries=new Dictionary<string,byte[]>{{"data\\mod.manifest",Serialize(staticAssets)["diagnostic.manifest"]},{"data\\additionalmaps\\mapmetadata_global.manifest",Serialize(globals)["diagnostic.manifest"]}};string package=Path.Combine(output,"fixture.big");File.WriteAllBytes(package,WorldBuilderAssetResolver.Pack(entries));
        string entry=Path.Combine(output,"Static_Mod.xml");File.WriteAllText(entry,"<!-- Reborn: declaration locations only; this is a metadata audit fixture, not playable compiled data. --><AssetDeclaration xmlns='uri:ea.com:eala:asset'>"+string.Concat(candidates.Append(modOwner).Select(a=>"<"+a.TypeName+" id='"+a.Name[(a.Name.IndexOf(':')+1)..]+"'/>"))+"</AssetDeclaration>");File.WriteAllText(Path.Combine(output,"source-input.json"),JsonSerializer.Serialize(new{GamePath=entry,Origins=candidates.Append(modOwner).Select(a=>new{Type=a.TypeName,Id=a.Name[(a.Name.IndexOf(':')+1)..],Path=entry})}));File.WriteAllText(Path.Combine(output,"asset-usage.json"),JsonSerializer.Serialize(schemaUses));
        var original=Console.Out;using var text=new StringWriter();try{Console.SetOut(text);SdkUnusedAssetAudit.Run(package,fakeSdk,output,entry);}finally{Console.SetOut(original);}string log=text.ToString();Require(log.Contains("Warning: UNUSEDASSET ' W3DMesh:UnusedW3DMesh '")&&log.Contains("Source: "+entry+"(")&&!log.Contains("UNUSEDASSET ' ArmorTemplate:UnusedArmorTemplate '")&&!log.Contains("UNUSEDASSET ' LogicCommandSet:UnusedLogicCommandSet '")&&!log.Contains("UNUSEDASSET ' PackedTextureImage:UnusedPackedTextureImage '")&&!log.Contains("UNUSEDASSET ' GameObject:UnusedGameObject '")&&!log.Contains("UNUSEDASSET ' UnitAbilityButtonTemplate:UnusedUnitAbilityButtonTemplate '")&&!log.Contains("UNUSEDASSET ' JoypadCommandBarButtonTemplate:UnusedJoypadCommandBarButtonTemplate '")&&!log.Contains("UNUSEDASSET ' ExperienceLevelTemplate:UnusedExperienceLevelTemplate '")&&!log.Contains("UNUSEDASSET ' AudioEvent:UnusedAudioEvent '")&&!log.Contains("UNUSEDASSET ' AudioEvent:SourceAudioRoot '")&&log.Contains("UNUSEDASSET ' AudioEvent:NeverUsed '"),"Final package audit missed cross-stream/weak/inherited use or source locations.");File.WriteAllText(Path.Combine(output,"audit.log"),log);Console.WriteLine("Reborn: unused asset audit: PASS (17 families, stock/mod strong and schema-typed weak refs, actual typed/local and source-only inheritance chains/receipts, dormant/absent-owner refusals, override precedence, runtime roots, cross-stream package union and source positions; no game/publication).");

        // Reborn: synthetic payloads exist only to supply valid linked metadata to the audit; no native-layout or gameplay claim is made.
        Dictionary<string,byte[]> Serialize(ManifestAsset[] assets)=>WorldBuilderAssetResolver.Serialize(assets.Select(a=>new WorldBuilderAssetResolver.Native(a,new byte[4],Array.Empty<byte>(),Array.Empty<byte>())).ToArray(),template,templateBytes);
    }

    // Reborn: fixtures retain the same typed hash identities used by the real compiler and final manifests.
    private static ManifestAsset Asset(string type,string name,params AssetId[] references){var id=SdkMissingDependencyAudit.Identity(type,name);return new(id.TypeId,id.InstanceId,1,2,0,references.Length,0,0,4,0,0,0,type+":"+name,"fixture.xml",references);}
    private static void Require(bool condition,string message){if(!condition)throw new InvalidDataException(message);}
}
